function escapeHtml(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function getKarmicTail(a, b, c) {
  const key = Array.isArray(a) ? a.join("-") : [a, b, c].join("-");
  return karmicTails[key] || null;
}

function getKarmicTailKey(result) {
  return [result.D1, result.D2, result.D].map(String).join("-");
}

function findKarmicTail(result) {
  const key = getKarmicTailKey(result);

  return {
    key,
    item: karmicTails[key] || null
  };
}

function normalizeText(text) {
  return String(text || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n");
}

function normalizeHeading(text) {
  return String(text || "")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .replace(/\u00A0/g, " ")
    .replace(/[：:]\s*$/, "")
    .replace(/\s+/g, " ")
    .trim();
}

