function detectHeadingType(text) {
  const clean = normalizeHeading(text);

  for (const [type, headings] of Object.entries(HEADING_GROUPS)) {
    if (
      headings.some((heading) => {
        return clean === normalizeHeading(heading);
      })
    ) {
      return type;
    }
  }

  return null;
}

function isBulletLine(line) {
  const clean = String(line || "").trim();

  return (
    clean.startsWith("•") ||
    clean.startsWith("·") ||
    clean.startsWith("- ") ||
    /^\d+\)/.test(clean)
  );
}

function splitRawIntoBlocks(raw) {
  const lines = normalizeText(raw).split("\n");

  const blocks = [];
  let currentLines = [];
  let blankCount = 0;
  let pendingBlankCount = 0;

  function pushCurrent() {
    const text = currentLines.join("\n").trim();

    if (!text) return;

    blocks.push({
      text,
      blankCountBefore: pendingBlankCount
    });

    currentLines = [];
    pendingBlankCount = 0;
  }

  lines.forEach((line) => {
    if (line.trim() === "") {
      blankCount++;

      if (currentLines.length > 0) {
        pushCurrent();
      }

      pendingBlankCount = blankCount;
      return;
    }

    blankCount = 0;
    currentLines.push(line);
  });

  pushCurrent();

  return blocks.map((block) => {
    const headingType = detectHeadingType(block.text);

    return {
      ...block,
      headingType,
      isHeading: Boolean(headingType),
      forcePageBreak: block.blankCountBefore >= 6,
      strongPageBreak: block.blankCountBefore >= 8
    };
  });
}

function findInlineHeading(line) {
  const rawLine = String(line || "").trim();
  const normalizedLine = normalizeHeading(rawLine);

  for (const [type, headings] of Object.entries(HEADING_GROUPS)) {
    for (const heading of headings) {
      const normalizedHeading = normalizeHeading(heading);

      if (normalizedLine === normalizedHeading) {
        return {
          type,
          title: normalizedHeading,
          rest: ""
        };
      }

      const variants = [
        normalizedHeading + ":",
        normalizedHeading + " :"
      ];

      for (const variant of variants) {
        if (rawLine.startsWith(variant)) {
          return {
            type,
            title: normalizedHeading,
            rest: rawLine.slice(variant.length).trim()
          };
        }
      }
    }
  }

  return null;
}

function splitBlockByEmbeddedHeadings(block) {
  const text = String(block.text || "").trim();

  if (!text) return [];

  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length === 0) return [];

  const result = [];
  let currentText = "";
  let currentBlock = {
    ...block,
    text: "",
    isHeading: false,
    headingType: null
  };

  function pushCurrentText() {
    const cleanText = String(currentText || "").trim();

    if (!cleanText) return;

    result.push({
      ...currentBlock,
      text: cleanText,
      isHeading: false,
      headingType: null
    });

    currentText = "";
  }

  lines.forEach((line, index) => {
    const foundHeading = findInlineHeading(line);

    if (foundHeading) {
      pushCurrentText();

      result.push({
        text: foundHeading.title,
        blankCountBefore: index === 0 ? block.blankCountBefore : 2,
        headingType: foundHeading.type,
        isHeading: true,
        forcePageBreak: index === 0 ? block.forcePageBreak : false,
        strongPageBreak: index === 0 ? block.strongPageBreak : false
      });

      currentBlock = {
        ...block,
        blankCountBefore: 0,
        forcePageBreak: false,
        strongPageBreak: false,
        isHeading: false,
        headingType: null
      };

      if (foundHeading.rest) {
        currentText += foundHeading.rest;
      }

      return;
    }

    currentText += (currentText ? "\n" : "") + line;
  });

  pushCurrentText();

  return result.length > 0 ? result : [block];
}

function findInlineHeading(line) {
  const cleanLine = String(line || "")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .replace(/\u00A0/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  for (const [type, headings] of Object.entries(HEADING_GROUPS)) {
    for (const heading of headings) {
      const cleanHeading = normalizeHeading(heading);

      if (cleanLine === cleanHeading) {
        return {
          type,
          title: cleanHeading,
          rest: ""
        };
      }

      if (cleanLine.startsWith(cleanHeading + ":")) {
        return {
          type,
          title: cleanHeading,
          rest: cleanLine.slice((cleanHeading + ":").length).trim()
        };
      }

      if (cleanLine.startsWith(cleanHeading + " :")) {
        return {
          type,
          title: cleanHeading,
          rest: cleanLine.slice((cleanHeading + " :").length).trim()
        };
      }
    }
  }

  return null;
}

function splitBlockByEmbeddedHeadings(block) {
  const text = String(block.text || "").trim();

  if (!text) return [];

  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length === 0) return [];

  const result = [];
  let currentText = "";
  let currentBlock = {
    ...block,
    text: "",
    isHeading: false,
    headingType: null
  };

  function pushCurrentText() {
    const cleanText = String(currentText || "").trim();

    if (!cleanText) return;

    result.push({
      ...currentBlock,
      text: cleanText,
      isHeading: false,
      headingType: null
    });

    currentText = "";
  }

  lines.forEach((line, index) => {
    const foundHeading = findInlineHeading(line);

    if (foundHeading) {
      pushCurrentText();

      result.push({
        text: foundHeading.title,
        blankCountBefore: index === 0 ? block.blankCountBefore : 2,
        headingType: foundHeading.type,
        isHeading: true,
        forcePageBreak: index === 0 ? block.forcePageBreak : false,
        strongPageBreak: index === 0 ? block.strongPageBreak : false
      });

      currentBlock = {
        ...block,
        blankCountBefore: 0,
        forcePageBreak: false,
        strongPageBreak: false,
        isHeading: false,
        headingType: null
      };

      if (foundHeading.rest) {
        currentText = foundHeading.rest;
      }

      return;
    }

    currentText += (currentText ? "\n" : "") + line;
  });

  pushCurrentText();

  return result.length > 0 ? result : [block];
}

function splitBlocksIntoSections(blocks) {
  const intro = [];
  const sections = [];
  let current = null;

  const expandedBlocks = [];

  blocks.forEach((block) => {
    expandedBlocks.push(...splitBlockByEmbeddedHeadings(block));
  });

  expandedBlocks.forEach((block) => {
    if (block.isHeading) {
      if (current) {
        sections.push(current);
      }

      current = {
        type: block.headingType,
        title: normalizeHeading(block.text),
        blankCountBefore: block.blankCountBefore,
        forcePageBreak: block.forcePageBreak,
        strongPageBreak: block.strongPageBreak,
        blocks: []
      };

      return;
    }

    if (current) {
      current.blocks.push(block);
    } else {
      intro.push(block);
    }
  });

  if (current) {
    sections.push(current);
  }

  return { intro, sections };
}

function sectionTextLength(section) {
  if (!section) return 0;

  const titleLength = section.title ? section.title.length : 0;
  const blocksLength = (section.blocks || []).reduce((sum, block) => {
    return sum + String(block.text || "").length;
  }, 0);

  return titleLength + blocksLength;
}

function blocksTextLength(blocks) {
  return (blocks || []).reduce((sum, block) => {
    return sum + String(block.text || "").length;
  }, 0);
}

function makePage(kind, sections, options = {}) {
  const length = sections.reduce((sum, section) => {
    if (section.kind === "intro") {
      return sum + blocksTextLength(section.blocks);
    }

    return sum + sectionTextLength(section);
  }, 0);

  let density = "balanced";

  if (length < 1700) {
    density = "center";
  } else if (length > 4300) {
    density = "dense";
  }

  return {
    kind,
    density,
    sections,
    title: options.title || "",
    key: options.key || "",
    name: options.name || ""
  };
}

function splitLongSectionByBlocks(section, maxChars) {
  const pages = [];
  let currentBlocks = [];
  let currentLength = 0;

  const sourceBlocks = [];

  (section.blocks || []).forEach((block) => {
    const text = String(block.text || "").trim();
    const lines = text.split("\n").map((line) => line.trim()).filter(Boolean);

    if (lines.length > 1 && lines.some(isBulletLine)) {
      lines.forEach((line) => {
        sourceBlocks.push({
          ...block,
          text: line,
          strongPageBreak: false,
          forcePageBreak: false
        });
      });
    } else {
      sourceBlocks.push(block);
    }
  });

  sourceBlocks.forEach((block) => {
    const blockLength = String(block.text || "").length + 80;

    if (
      currentBlocks.length > 0 &&
      (currentLength + blockLength > maxChars || block.strongPageBreak || block.forcePageBreak)
    ) {
      pages.push({
        ...section,
        blocks: currentBlocks
      });

      currentBlocks = [];
      currentLength = 0;
    }

    currentBlocks.push(block);
    currentLength += blockLength;
  });

  if (currentBlocks.length > 0) {
    pages.push({
      ...section,
      blocks: currentBlocks
    });
  }

  return pages;
}

function splitAuthorSection(section) {
  const authorPages = [];
  let currentBlocks = [];
  let currentLength = 0;

  const blocks = section.blocks || [];

  blocks.forEach((block, index) => {
    const blockLength = String(block.text || "").length;

    // Авторский заголовок занимает место, поэтому первая страница должна быть короче.
    // Так текст не будет слепляться в одну плотную простыню.
    const maxChars = authorPages.length === 0 ? 2600 : 3000;

    const shouldStartNewPage =
      currentBlocks.length > 0 &&
      (
        currentLength + blockLength > maxChars ||
        block.strongPageBreak ||
        block.forcePageBreak
      );

    if (shouldStartNewPage) {
      authorPages.push({
        ...section,
        title: authorPages.length === 0 ? section.title : "",
        blocks: currentBlocks
      });

      currentBlocks = [];
      currentLength = 0;
    }

    currentBlocks.push(block);
    currentLength += blockLength;

    if (index === blocks.length - 1 && currentBlocks.length > 0) {
      authorPages.push({
        ...section,
        title: authorPages.length === 0 ? section.title : "",
        blocks: currentBlocks
      });
    }
  });

  if (authorPages.length === 0) {
    authorPages.push(section);
  }

  return authorPages;
}

function buildKarmicPages(found) {
  const raw = found.item.text || "";
  const parsed = splitBlocksIntoSections(splitRawIntoBlocks(raw));

  const introBlocks = parsed.intro || [];
  const sections = parsed.sections || [];

  const energyIntroSections = sections.filter((s) => s.type === "energyIntro");
  const pastSections = sections.filter((s) => s.type === "past");
  const presentSections = sections.filter((s) => s.type === "present");
  const strengthsSections = sections.filter((s) => s.type === "strengths");
  const problemsSections = sections.filter((s) => s.type === "problems");
  const tasksSections = sections.filter((s) => s.type === "tasks");
  const authorSection = sections.find((s) => s.type === "author");

  const pages = [];

  const titlePageSections = [];
const overflowSections = [];

const introSection = {
  kind: "intro",
  title: "",
  blocks: introBlocks
};

const titleParts = splitLongSectionByBlocks(introSection, 1800);

if (titleParts.length > 0) {
  titlePageSections.push(titleParts[0]);

  for (let i = 1; i < titleParts.length; i++) {
    overflowSections.push(titleParts[i]);
  }
}

energyIntroSections.forEach((section) => {
  const parts = splitLongSectionByBlocks(section, 1800);

  parts.forEach((part) => {
    const currentLength = titlePageSections.reduce((sum, s) => {
      if (s.kind === "intro") {
        return sum + blocksTextLength(s.blocks);
      }

      return sum + sectionTextLength(s);
    }, 0);

    const partLength =
      part.kind === "intro"
        ? blocksTextLength(part.blocks)
        : sectionTextLength(part);

    if (currentLength + partLength <= 2600) {
      titlePageSections.push(part);
    } else {
      overflowSections.push(part);
    }
  });
});

pages.push(
  makePage("title", titlePageSections, {
    key: found.key,
    name: found.item.title
  })
);

overflowSections.forEach((section) => {
  pages.push(makePage("fill", [section]));
});

  // Past + present: если маленький хвост, не создаём отдельную пустую страницу,
  // а присоединяем к предыдущей странице.
  const normalSections = [...pastSections, ...presentSections];

  normalSections.forEach((section) => {
    const parts = splitLongSectionByBlocks(section, 3000);

    parts.forEach((part) => {
      const len = sectionTextLength(part);
      const lastPage = pages[pages.length - 1];
      const lastLen = lastPage
        ? lastPage.sections.reduce((sum, s) => {
            if (s.kind === "intro") return sum + blocksTextLength(s.blocks);
            return sum + sectionTextLength(s);
          }, 0)
        : 0;

      if (
        lastPage &&
        lastPage.kind !== "author-start" &&
        lastPage.kind !== "author-continue" &&
        len < 900 &&
        lastLen < 3900
      ) {
        lastPage.sections.push(part);
        lastPage.density = "balanced";
      } else {
        pages.push(makePage("fill", [part]));
      }
    });
  });

  const strengthsProblems = [...strengthsSections, ...problemsSections];

  if (strengthsProblems.length > 0) {
    const total = strengthsProblems.reduce((sum, section) => sum + sectionTextLength(section), 0);

    if (total <= 3000) {
      pages.push(makePage("strengths-problems", strengthsProblems));
    } else {
      strengthsProblems.forEach((section) => {
        const parts = splitLongSectionByBlocks(section, 3000);
        parts.forEach((part) => pages.push(makePage("strengths-problems", [part])));
      });
    }
  }

  if (tasksSections.length > 0) {
    let current = [];
    let currentLength = 0;

    tasksSections.forEach((section) => {
      const len = sectionTextLength(section);

      if (current.length > 0 && currentLength + len > 3200) {
        pages.push(makePage("tasks", current));
        current = [];
        currentLength = 0;
      }

      current.push(section);
      currentLength += len;
    });

    if (current.length > 0) {
      pages.push(makePage("tasks", current));
    }
  }

  if (authorSection) {
    const authorParts = splitAuthorSection(authorSection);

    authorParts.forEach((part, index) => {
      pages.push(
        makePage(index === 0 ? "author-start" : "author-continue", [part])
      );
    });
  }

  return pages;
}

function getPageTextLength(page) {
  if (!page || !page.sections) return 0;

  return page.sections.reduce((sum, section) => {
    if (section.kind === "intro") {
      return sum + blocksTextLength(section.blocks);
    }

    return sum + sectionTextLength(section);
  }, 0);
}

function mergeTinyKarmicPages(pages) {
  const result = [];

  pages.forEach((page) => {
    const pageLen = getPageTextLength(page);
    const previous = result[result.length - 1];
    const previousLen = getPageTextLength(previous);

    const isNormalTinyPage =
      previous &&
      pageLen < 1000 &&
      previousLen < 4100 &&
      page.kind !== "author-start" &&
      previous.kind !== "author-start" &&
      previous.kind !== "author-continue";

    const isTinyAuthorContinue =
      previous &&
      page.kind === "author-continue" &&
      previous.kind === "author-continue" &&
      pageLen < 1500 &&
      previousLen < 3900;

    if (isNormalTinyPage || isTinyAuthorContinue) {
      previous.sections.push(...page.sections);

      const mergedLen = previousLen + pageLen;

      if (mergedLen < 1700) {
        previous.density = "center";
      } else if (mergedLen > 4300) {
        previous.density = "dense";
      } else {
        previous.density = "balanced";
      }

      return;
    }

    result.push(page);
  });

  return result;
}

function renderInlineText(text) {
  let safe = escapeHtml(text);

  safe = safe.replace(
    /^\((\d{1,2})\)\s*/,
    '<span class="energy-marker">($1)</span> '
  );

  return safe;
}

function renderBlock(block) {
  const text = String(block.text || "").trim();
  if (!text) return "";

  const lines = text.split("\n").map((line) => line.trim()).filter(Boolean);

  if (lines.length > 1 && lines.every(isBulletLine)) {
    const items = lines.map((line) => {
      const cleaned = line.replace(/^(•|·|-|\d+\))\s*/, "");
      return `<li>${renderInlineText(cleaned)}</li>`;
    }).join("");

    return `<ul class="karmic-list">${items}</ul>`;
  }

  if (lines.length > 1 && lines.some(isBulletLine)) {
    return lines.map((line) => {
      if (isBulletLine(line)) {
        const cleaned = line.replace(/^(•|·|-|\d+\))\s*/, "");
        return `<ul class="karmic-list single"><li>${renderInlineText(cleaned)}</li></ul>`;
      }

      return `<p>${renderInlineText(line)}</p>`;
    }).join("");
  }

  const compact = text.replace(/\n+/g, " ").replace(/\s+/g, " ").trim();

  return `<p>${renderInlineText(compact)}</p>`;
}

function renderBlocks(blocks) {
  return (blocks || []).map(renderBlock).join("");
}

function renderSection(section) {
  if (!section) return "";

  if (section.kind === "intro") {
    return `
      <div class="karmic-section karmic-section-intro">
        <div class="karmic-text">
          ${renderBlocks(section.blocks)}
        </div>
      </div>
    `;
  }

  const title = section.title
    ? `<h3 class="karmic-subtitle karmic-subtitle-${section.type}">${escapeHtml(section.title)}</h3>`
    : "";

  return `
    <div class="karmic-section karmic-section-${section.type}">
      ${title}
      <div class="karmic-text">
        ${renderBlocks(section.blocks)}
      </div>
    </div>
  `;
}

function renderKarmicPage(page, index) {
  const titleHTML = page.kind === "title"
    ? `
      <div class="karmic-title-block">
        <div class="karmic-overline">Karmický ocas</div>
        <h2>${escapeHtml(page.name || "Karmický ocas")}</h2>
        <div class="karmic-combination">${escapeHtml(page.key)}</div>
      </div>
    `
    : "";

  const sectionsHTML = page.sections.map(renderSection).join("");

  return `
    <section class="karmic-print-page karmic-page-${page.kind} karmic-density-${page.density}">
      <div class="karmic-print-inner">
        ${titleHTML}
        ${sectionsHTML}
      </div>
    </section>
  `;
}

function renderKarmicTailHTML(result) {
  const found = findKarmicTail(result);

  if (!found.item) {
    return `
      <div class="energy-item programs-card karmic-tail-card">
        <section class="karmic-print-page karmic-density-center">
          <div class="karmic-print-inner">
            <div class="karmic-title-block">
              <div class="karmic-overline">Karmický ocas</div>
              <h2>Výklad není nahraný</h2>
              <div class="karmic-combination">${escapeHtml(found.key)}</div>
            </div>
            <div class="karmic-text">
              <p>Pro tuto kombinaci zatím není v databázi nahraný výklad karmického ocasu.</p>
            </div>
          </div>
        </section>
      </div>
    `;
  }

  const pages = buildKarmicPages(found);

  return `
    <div class="energy-item programs-card karmic-tail-card">
      ${pages.map(renderKarmicPage).join("")}
    </div>
  `;
}

if (typeof window !== "undefined") {
  window.karmicTails = karmicTails;
  window.karmicTailCanonicalKeys = karmicTailCanonicalKeys;
  window.getKarmicTail = getKarmicTail;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    karmicTails,
    karmicTailCanonicalKeys,
    getKarmicTail,
    findKarmicTail,
    renderKarmicTailHTML
  };
}